parameters.jsCode:
const groqResponse = items[0].json;
const rawContent = groqResponse.choices[0].message.content;

let parsed;
try {
  parsed = JSON.parse(rawContent);
} catch (e) {
  const match = rawContent.match(/\{[\s\S]*\}/);
  if (match) {
    parsed = JSON.parse(match[0]);
  } else {
    throw new Error('Não foi possível extrair JSON da resposta do Groq: ' + rawContent);
  }
}

return [{
  json: {
    status_qualificacao: parsed.status_qualificacao ?? 'Indefinido',
    resumo_necessidade: parsed.resumo_necessidade ?? '',
    resposta_sugerida: parsed.resposta_sugerida ?? ''
  }
}];
